    function fmtLoc(s, type) {
        const code = type === 'pickup' ? s.origin_airport : s.destination_airport;
        const addr = type === 'pickup' ? s.pickup_address : s.dropoff_address;

        let html = '<div class="flex flex-col gap-0.5 max-w-[140px]">';
        
        // Airport code badge
        if (code && code.length >= 3) {
            html += '<span class="font-black text-white bg-slate-700 px-2 py-0.5 rounded text-xs tracking-wide w-fit">' + code + '</span>';
        }
        
        // Address with truncation
        if (addr && addr.length > 2) {
            html += '<span class="address-truncate text-slate-300 text-xs" title="' + addr + '">' + addr + '</span>';
        } else if (!code) {
            html += '<span class="text-slate-600 text-xs italic">N/A</span>';
        }
        
        html += '</div>';
        return html;
    }

    // Urgency configuration
    const urgencyConfig = {
        'OVERDUE': { label: 'Overdue', bg: 'bg-red-500', text: 'text-red-400', border: 'border-red-500' },
        'CRITICAL': { label: 'Critical', bg: 'bg-orange-500', text: 'text-orange-400', border: 'border-orange-500' },
        'WARNING': { label: 'Warning', bg: 'bg-yellow-500', text: 'text-yellow-400', border: 'border-yellow-500' },
        'NORMAL': { label: '', bg: '', text: '', border: '' },
        'FAILED': { label: 'Failed', bg: 'bg-gray-500', text: 'text-gray-400', border: 'border-gray-500' }
    };
    
    function getUrgencyPriority(urgency, status) {
        // Only show urgency for pending/assigned orders
        if (!['PENDING', 'ASSIGNED'].includes(status)) return 999;
        const priority = { 'OVERDUE': 0, 'CRITICAL': 1, 'WARNING': 2, 'NORMAL': 3, 'FAILED': 4 };
        return priority[urgency] || 999;
    }
    
    function formatTimeRemaining(targetTime) {
        if (!targetTime) return '';
        const now = new Date();
        const target = new Date(targetTime);
        const diffMs = target.getTime() - now.getTime();
        const diffMinutes = Math.floor(diffMs / 60000);
        
        if (diffMinutes < 0) {
            const overdue = Math.abs(diffMinutes);
            if (overdue < 60) return overdue + 'm overdue';
            return Math.floor(overdue / 60) + 'h overdue';
        }
        if (diffMinutes < 60) return diffMinutes + 'm';
        return Math.floor(diffMinutes / 60) + 'h ' + (diffMinutes % 60) + 'm';
    }

