export const LOGIN_HTML = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Login - LuggageLink Ops</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <script>
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            slate: {
              50: '#f8fafc', 100: '#f1f5f9', 200: '#e2e8f0', 300: '#cbd5e1',
              400: '#94a3b8', 500: '#64748b', 600: '#475569', 700: '#334155',
              800: '#1e293b', 900: '#0f172a', 950: '#020617',
            }
          }
        }
      }
    }
  </script>
  <script src="https://unpkg.com/lucide@latest"></script>
  <style>
    body { font-family: sans-serif; }
    .shake { animation: shake 0.5s cubic-bezier(.36,.07,.19,.97) both; }
    @keyframes shake {
      10%, 90% { transform: translate3d(-1px, 0, 0); }
      20%, 80% { transform: translate3d(2px, 0, 0); }
      30%, 50%, 70% { transform: translate3d(-4px, 0, 0); }
      40%, 60% { transform: translate3d(4px, 0, 0); }
    }
  </style>
</head>
<body class="bg-slate-900 text-slate-100 min-h-screen flex items-center justify-center">
  
  <div class="w-full max-w-md p-8">
    <div class="text-center mb-8">
      <div class="bg-purple-600 w-16 h-16 rounded-xl flex items-center justify-center mx-auto mb-4 shadow-lg shadow-purple-500/20">
        <i data-lucide="tower-control" class="w-8 h-8"></i>
      </div>
      <h1 class="text-2xl font-bold">LuggageLink Ops</h1>
      <p class="text-slate-400 mt-2">Operations Console</p>
    </div>

    <form id="login-form" class="bg-slate-800 rounded-xl p-6 border border-slate-700 shadow-xl">
      <div class="mb-4">
        <label class="block text-sm font-medium text-slate-300 mb-2">PIN Code</label>
        <div class="relative">
          <input 
            type="password" 
            id="pin-input" 
            maxlength="10"
            class="w-full bg-slate-900 border border-slate-600 rounded-lg px-4 py-3 text-center text-xl tracking-widest focus:outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500 transition-colors"
            placeholder="••••"
            autocomplete="off"
          >
          <button type="button" onclick="togglePinVisibility()" class="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-300">
            <i data-lucide="eye" class="w-5 h-5" id="eye-icon"></i>
          </button>
        </div>
      </div>

      <div id="error-message" class="hidden mb-4 p-3 bg-red-900/30 border border-red-500/30 rounded-lg text-red-400 text-sm text-center">
        Invalid PIN code
      </div>

      <button 
        type="submit" 
        id="login-button"
        class="w-full bg-purple-600 hover:bg-purple-500 text-white font-semibold py-3 rounded-lg transition-colors flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
      >
        <i data-lucide="log-in" class="w-5 h-5"></i>
        <span>Sign In</span>
      </button>
    </form>

    <div class="mt-6 text-center text-xs text-slate-500">
      <p>Secure Operations Environment</p>
      <p class="mt-1">Authorized personnel only</p>
    </div>
  </div>

  <script>
    lucide.createIcons();

    function togglePinVisibility() {
      const input = document.getElementById('pin-input');
      const icon = document.getElementById('eye-icon');
      
      if (input.type === 'password') {
        input.type = 'text';
        icon.setAttribute('data-lucide', 'eye-off');
      } else {
        input.type = 'password';
        icon.setAttribute('data-lucide', 'eye');
      }
      lucide.createIcons();
    }

    document.getElementById('login-form').addEventListener('submit', async (e) => {
      e.preventDefault();
      
      const pin = document.getElementById('pin-input').value;
      const button = document.getElementById('login-button');
      const errorMessage = document.getElementById('error-message');
      const form = document.getElementById('login-form');
      
      button.disabled = true;
      button.innerHTML = '<i data-lucide="loader-2" class="w-5 h-5 animate-spin"></i><span>Signing in...</span>';
      lucide.createIcons();
      errorMessage.classList.add('hidden');
      form.classList.remove('shake');

      try {
        const res = await fetch('/api/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ pin })
        });

        const data = await res.json();

        if (res.ok && data.success) {
          window.location.href = '/loading?redirect=/';
        } else {
          throw new Error(data.error || 'Login failed');
        }
      } catch (err) {
        errorMessage.textContent = err.message || 'Invalid PIN code';
        errorMessage.classList.remove('hidden');
        form.classList.add('shake');
        setTimeout(() => form.classList.remove('shake'), 500);
        
        button.disabled = false;
        button.innerHTML = '<i data-lucide="log-in" class="w-5 h-5"></i><span>Sign In</span>';
        lucide.createIcons();
      }
    });

    // Focus input on load
    document.getElementById('pin-input').focus();
  </script>
</body>
</html>
`;
